budget { tokens: 2000  calls: 5 }

tool StatusPage {
    use: http
    base_url: env.STATUS_PAGE_URL
    allow_paths: "/"
    methods: "GET"
}

tool EpisodeState {
    use: file
    root: "state"
    mode: readwrite
}

tool OnCallWebhook {
    use: webhook
    url: env.STATUS_WEBHOOK
    format: json
}

intentclassifier StatusClassifier {
    model: "gemini-2.5-flash"
    samples: 3
    choose kind: outage | recovered | operational | unsure
    confidence at least 0.8 else unsure
}

workflow Main(status_page_text, episode_active) {
    intentclassify StatusClassifier on status_page_text -> status retry 2 backoff 2s timeout 15s on_failure {
        human_prompt "Status classification failed. Review the current status page and reconcile any pending outage episode." -> operator_review
        halt "Classification failed; operator review is required."
    }

    alt (status.kind == "unsure") {
        human_prompt "Review this ambiguous status-page text and reconcile any pending outage episode:\n{status_page_text}" -> operator_review
        return "Operator review requested; no alert or state change was made."
    } else {
        alt (status.kind == "outage") {
            alt (episode_active == true) {
                return "An outage episode is already active; no new alert is requested."
            } else {
                human_prompt "A new outage was classified. Approve recording a pending episode before sending an alert? (yes/no)" -> state_approval
                alt (state_approval == "yes") {
                    human_prompt "Approve sending one on-call alert for this outage episode? (yes/no)" -> alert_approval
                    alt (alert_approval == "yes") {
                        return "Operator approved the pending episode and one alert. Reconcile state if the send or state update fails."
                    } else {
                        return "Alert not approved; operator reconciliation is required."
                    }
                } else {
                    return "State write not approved; no alert was sent."
                }
            }
        } else {
            alt (status.kind == "recovered") {
                alt (episode_active == true) {
                    human_prompt "Recovery was explicitly reported. Approve clearing the active episode state? (yes/no)" -> recovery_approval
                    alt (recovery_approval == "yes") {
                        return "Recovery state clear approved; monitoring may re-arm after the state update."
                    } else {
                        return "Recovery state clear not approved; operator reconciliation is required."
                    }
                } else {
                    return "Recovery reported with no active episode; no state change is needed."
